 'localize':async()=>{const q={PosX:+$('#loc-x').value,PosY:+$('#loc-y').value,PosZ:+$('#loc-z').value,Yaw:+$('#loc-yaw').value};modal('确认定位初始化',`<p>将机器人在地图中的位置设为 X=${q.PosX} m、Y=${q.PosY} m、Yaw=${q.Yaw} rad。请确认这些数值与真实位置一致。</p>`,[{label:'确认发送',ui:'confirm-localize'}]);ui['confirm-localize']=async()=>{await api('/api/localize',q);$('#modal').close();toast('定位请求已发送，请等待状态收敛');};},
