 'train-refresh':fetchTraining,'train-stop':async()=>{const j=trainState.jobs.find(j=>j.status==='running');if(!j)throw Error('没有运行中的训练任务');await api('/api/train/stop',{id:j.id});toast('已请求停止训练任务');await fetchTraining();},
