function maintenanceModal(){modal('设备维护',`<div class="segmented"><button data-ui="maint-led" class="active">自定义灯语</button><button data-ui="maint-sleep">自动休眠</button><button data-ui="maint-time">时间同步</button></div><div id="maintenance-body" class="section-gap"></div>`);ui['maint-led']();}
ui['maint-led']=()=>{html('maintenance-body',select('灯光模式','led-type',[[0,'常亮'],[1,'填充流水'],[2,'移动流水'],[4,'呼吸'],[5,'闪烁']])+`<div class="form-grid">${select('头灯颜色','led-front',[[2,'绿色'],[1,'白色'],[3,'蓝色'],[0,'黑色']])}${select('尾灯颜色','led-rear',[[2,'绿色'],[1,'白色'],[3,'蓝色'],[0,'黑色']])}</div>`+field('变化周期 / s','led-cycle',2,'number')+btn('应用灯语','apply-led','primary')+btn('恢复默认灯语','default-led'));};
ui['apply-led']=()=>api('/api/maintenance',{action:'led',type:+$('#led-type').value,front:+$('#led-front').value,rear:+$('#led-rear').value,cycle:+$('#led-cycle').value}).then(()=>toast('灯语请求已发送'));
ui['default-led']=()=>api('/api/maintenance',{action:'led',enabled:false}).then(()=>toast('已发送恢复默认灯语请求'));
ui['maint-sleep']=()=>html('maintenance-body',field('自动休眠等待 / 分钟（5–30）','sleep-minutes',5,'number')+btn('启用自动休眠','auto-sleep-on','primary')+btn('关闭自动休眠','auto-sleep-off'));
ui['auto-sleep-on']=()=>api('/api/sleep',{auto:true,minutes:+$('#sleep-minutes').value}).then(()=>toast('自动休眠配置已发送'));
ui['auto-sleep-off']=()=>api('/api/sleep',{auto:false}).then(()=>toast('禁用自动休眠请求已发送'));
ui['maint-time']=()=>html('maintenance-body',field('GPS 同步间隔 / 小时','gps-interval',12,'number')+btn('启用 GPS 同步','gps-time-on','primary')+btn('禁用 GPS 同步','gps-time-off')+'<div class="divider"></div>'+field('外部时间 / 机器人当地时间','external-time',new Date().toLocaleString('sv-SE',{timeZone:'Asia/Shanghai',hour12:false}))+btn('同步外部时间','set-time'));
ui['gps-time-on']=()=>api('/api/maintenance',{action:'gps-time',enabled:true,interval:+$('#gps-interval').value}).then(()=>toast('GPS 时间同步请求已发送'));
ui['gps-time-off']=()=>api('/api/maintenance',{action:'gps-time',enabled:false}).then(()=>toast('禁用 GPS 同步请求已发送'));
ui['set-time']=()=>confirmAction('同步机器人系统时间','会影响整机时间与日志时间戳。请确认所有运动与数据采集已停止。','/api/maintenance',{action:'external-time',time:$('#external-time').value});
function confirmAction(title,body,path,data){modal(title,`<p>${esc(body)}</p>`,[{label:'确认执行',ui:'confirm-generic'}]);ui['confirm-generic']=async()=>{const r=await api(path,data);$('#modal').close();toast(r.message||'请求已提交，请核对状态反馈');await fetchState();};}
async function runRoute(id){const options={id,nav_mode:+($('#nav-mode')?.value||0),speed:+($('#nav-speed')?.value||1),gait:$('#nav-gait')?.value||'flat',manner:+($('#nav-manner')?.value||0)};await api('/api/nav/start',options);toast(S.mode==='demo'?'演示巡检任务已开始':'路线已提交');await fetchState();}
async function nosAction(action){text('nos-output','正在请求 NOS…');try{const r=action?await api('/api/nos/action',{action,name:$('#nos-map-name').value}):await api('/api/nos/status');text('nos-output',JSON.stringify(r,null,2));}catch(e){text('nos-output',e.message);}}
function cameraOpen(cam){if(S.mode==='demo'){toast('当前为演示模式，没有实机视频流',true);return;}const image=$('#camera-'+cam),over=$('#ppe-overlay')?.checked&&S.ppe.enabled&&S.ppe.camera===cam;image.hidden=false;image.alt=cam==='front'?'前置相机实时画面':'后置相机实时画面';image.onerror=()=>{$('#placeholder-'+cam).hidden=false;image.hidden=true;toast('视频连接失败，请检查 OpenCV、RTSP 与摄像头状态',true);};image.onload=()=>{$('#placeholder-'+cam).hidden=true;text('cam-'+cam+'-tag',over?'YOLO LIVE':'LIVE');};image.src='/video/'+(over?'ppe':cam)+'?t='+Date.now();}
for(const cam of ['front','rear']){ui['camera-'+cam]=()=>cameraOpen(cam);ui['camera-close-'+cam]=()=>{const img=$('#camera-'+cam);img.removeAttribute('src');img.hidden=true;$('#placeholder-'+cam).hidden=false;text('cam-'+cam+'-tag','STANDBY');};}
document.addEventListener('click',async e=>{try{const moduleButton=e.target.closest('[data-module]');if(moduleButton){const found=modules.find(m=>m.id===moduleButton.dataset.module),target=found&&found.pages.find(k=>pages[k]);if(target)return navigate(target);}const nav=e.target.closest('[data-page]');if(nav)return navigate(nav.dataset.page);const el=e.target.closest('button');if(!el)return;if(el.dataset.action){stopMotion();const r=await api('/api/cmd',{action:el.dataset.action});toast(el.dataset.action==='estop'?'软急停请求已发出，请核对机身状态':r?.message||(S.mode==='demo'?'演示操作完成':'命令已发送，等待状态确认'));await fetchState();return;}if(el.dataset.ui&&ui[el.dataset.ui])return await ui[el.dataset.ui]();if(el.dataset.leg){selectedLeg=el.dataset.leg;drafts={};$$('[data-leg]').forEach(b=>b.classList.toggle('active',b.dataset.leg===selectedLeg));ui['clear-preview']();renderJointSliders();return;}if(el.dataset.jointApply!==undefined){const i=+el.dataset.jointApply,value=+($(`.joint-number[data-index="${i}"]`).value);await jointOp('set',{index:i,value});ui['clear-preview']();return;}if(el.dataset.removePoint!==undefined){points.splice(+el.dataset.removePoint,1);if(page==='navigation')navIntent=points.length>1?'route':'goal';renderPoints();return;}if(el.dataset.routeLoad){const r=S.routes.find(r=>r.id===el.dataset.routeLoad);navIntent='route';routeId=r.id;mapId=r.map_id;points=structuredClone(r.points);if(page!=='navigation')navigate('navigation');else render();return;}if(el.dataset.routeRun)return await runRoute(el.dataset.routeRun);if(el.dataset.routeDelete){await api('/api/route/delete',{id:el.dataset.routeDelete});await fetchState();return;}if(el.dataset.posePreview){preview(S.poses.find(p=>p.id===el.dataset.posePreview).positions);return;}if(el.dataset.poseApply){await jointOp('pose',{positions:S.poses.find(p=>p.id===el.dataset.poseApply).positions});return;}}catch(e){if(!e.message.startsWith('代理')&&!$('.toast.error'))toast(e.message,true);}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='motion-speed')text('speed-label',fmt(t.value,2));if(t.id==='leg-height')text('leg-height-label',t.value+' cm');if(t.id==='fault-search'){faultSearch=t.value;renderCatalog();}if(t.matches('.joint-range,.joint-number')){const i=+t.dataset.index,v=+t.value;$$(`[data-index="${i}"]`).forEach(el=>{if(el!==t)el.value=v;});drafts[i]=v;const poses=S.joints.map(j=>drafts[j.index]??j.position??0);if(i%4!==3)preview(poses);}});
document.addEventListener('change',async e=>{try{const t=e.target;if(t.id==='map-select'){mapId=t.value;points=[];routeId=null;render();}if(t.dataset.point!==undefined){points[+t.dataset.point][t.dataset.key]=+t.value;drawMap();}if(t.id==='yaml-file'&&t.files[0]){const str=await t.files[0].text(),r=str.match(/^resolution:\s*([\d.eE+-]+)/m),o=str.match(/^origin:\s*\[([^\]]+)\]/m);if(r)$('#map-res').value=r[1];if(o){const vals=o[1].split(',').map(Number);if(Math.abs(vals[2]||0)>.00001)throw Error('地图原点 yaw 需为 0');$('#map-x').value=vals[0];$('#map-y').value=vals[1];}}if(t.id==='ppe-overlay'&&S.ppe.enabled)cameraOpen($('#ppe-camera').value);}catch(e){toast(e.message,true);}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='connection-form'){await api('/api/connect',{mode:$('#connect-mode').value,ip:$('#robot-ip').value,port:+$('#robot-port').value});session=null;await fetchState();toast('连接配置已应用');}if(e.target.id==='settings-form'){await api('/api/settings',{sdk:$('#sdk-url').value,train:$('#train-url').value,nos:$('#nos-url').value});await fetchState();toast('本次连接设置已保存');}if(e.target.id==='training-form'){await api('/api/train/start',trainConfig());await fetchTraining();toast(S.mode==='demo'?'演示任务已启动，曲线为合成数据':'训练任务已提交到工作站');}if(e.target.id==='map-import-form'){const file=$('#pgm-file').files[0];if(!file)throw Error('请选择 PGM 地图');if(file.size>12e6)throw Error('地图文件不能超过 12 MB');const r=await api('/api/maps/import',{name:$('#map-name').value,pgm:await readFileBase64(file),resolution:+$('#map-res').value,origin:[+$('#map-x').value,+$('#map-y').value,0]});mapId=r.map.id;await fetchState();render();toast('地图已导入');}if(e.target.id==='auth-form'){await api('/api/auth',{token:$('#auth-token').value});$('#auth-token').value='';authPending=false;$('#modal').close();await fetchState();catalog=(await api('/api/catalog',undefined,true)).errors;}}catch(e){if(!$('.toast.error'))toast(e.message,true);}});
document.addEventListener('click',e=>{
 const tab=e.target.closest('[data-vision-tab]');if(!tab)return;
 visionTab=tab.dataset.visionTab;
 $$('[data-vision-tab]').forEach(b=>{const active=b===tab;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});
 $$('[data-vision-pane]').forEach(p=>{p.hidden=p.dataset.visionPane!==visionTab;});
 const cameras=document.querySelector('.camera-grid');if(cameras)cameras.hidden=visionTab!=='ppe';
 if(visionTab==='people'&&typeof paintPeople==='function')paintPeople();
 if(visionTab!=='people'&&typeof closePeoplePreview==='function')closePeoplePreview();
});
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-velocity]');if(!b)return;e.preventDefault();b.setPointerCapture(e.pointerId);b.classList.add('pressed');startMotion(b.dataset.velocity.split(',').map(Number));});
document.addEventListener('pointerup',stopMotion);document.addEventListener('pointercancel',stopMotion);
document.addEventListener('click',e=>{const svg=e.target.closest('#nav-map');if(!svg||e.target.closest('.map-tools'))return;const m=selectedMap(),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const v=p.matrixTransform(svg.getScreenCTM().inverse());if(v.x<0||v.y<0||v.x>m.width||v.y>m.height)return;const x=m.origin[0]+v.x*m.resolution,y=m.origin[1]+(m.height-v.y)*m.resolution;if(mapTool==='pose'){if($('#loc-x')){$('#loc-x').value=x.toFixed(2);$('#loc-y').value=y.toFixed(2);toast('初始位置已填入，请确认 Yaw 后提交');}}else{const point={x:+x.toFixed(2),y:+y.toFixed(2),yaw:0,type:1};points.push(point);if(page==='navigation')navIntent=points.length>1?'route':'goal';renderPoints();}});
function typingTarget(target){if(!target||typeof target.closest!=='function')return false;if(target.closest('textarea,[contenteditable="true"]'))return true;return target.tagName==='INPUT'&&['text','search','password','email','url','tel','number'].includes(target.type);}
let jointsKeyNoticeAt=0;
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!typingTarget(e.target)){e.preventDefault();stopMotion();api('/api/cmd',{action:'stop'}).catch(()=>{});if(session){api('/api/joints/stop',{},true).catch(()=>{});session=null;}return;}if(typingTarget(e.target)||$('#modal').open)return;const key=e.key.toLowerCase();if(!['w','a','s','d','q','e'].includes(key))return;e.preventDefault();
 if(page==='joints'&&session){if(!jointsKeyNoticeAt||Date.now()-jointsKeyNoticeAt>4000){jointsKeyNoticeAt=Date.now();toast('关节控制会话进行中，先结束关节控制再使用方向键');}return;}
 if(e.target.matches?.('input,select')&&e.target.blur)e.target.blur();keys.add(key);const v=[+keys.has('w')-+keys.has('s'),+keys.has('a')-+keys.has('d'),+keys.has('q')-+keys.has('e')];
 if(page==='sdk'&&typeof sdkVelocityStart==='function')return sdkVelocityStart(v);
 startMotion(v);});
document.addEventListener('keyup',e=>{const key=e.key.toLowerCase();if(!keys.has(key))return;keys.delete(key);const v=[+keys.has('w')-+keys.has('s'),+keys.has('a')-+keys.has('d'),+keys.has('q')-+keys.has('e')];if(page==='sdk'&&typeof sdkVelocityStop==='function'){if(!keys.size)sdkVelocityStop();else sdkVelocityStart(v);return;}if(!keys.size)return stopMotion();startMotion(v);});
function blurStop(){stopMotion();if(session){api('/api/joints/stop',{},true).catch(()=>{});session=null;}}
window.addEventListener('blur',blurStop);document.addEventListener('visibilitychange',()=>{if(document.hidden)blurStop();});
window.addEventListener('beforeunload',()=>{if(session||motionTimer)navigator.sendBeacon('/api/joints/stop',new Blob(['{}'],{type:'application/json'}));});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(pages[p]&&p!==page)navigate(p);});
window.addEventListener('resize',()=>{if(S)update();updateTraining();});
setInterval(()=>{text('live-clock',new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}));},1000);
setInterval(()=>{if(!document.hidden)fetchState();},500);
setInterval(()=>{if(page==='training'&&!document.hidden)fetchTraining();},1500);
setInterval(()=>{if(page==='joints'&&session&&!document.hidden)api('/api/joints/lease',{session},true).catch(()=>{session=null;});},200);
document.addEventListener('DOMContentLoaded',async()=>{try{const auth=await api('/api/auth');if(auth.required&&!auth.authenticated){modal('登录机器人操作平台',`<form id="auth-form">${field('平台访问口令','auth-token','','password')}<button class="btn primary wide" type="submit">登录</button></form>`);return;}else{authPending=false;await fetchState();}const cat=await api('/api/catalog',undefined,true);catalog=cat.errors;if(page==='diagnostics')renderCatalog();}catch(e){toast('无法连接平台服务，请检查启动终端。',true);}});

// Always show the outcome of the asynchronous sequence, not only acceptance.
const greetingOriginalUpdate=update;
function greetingStatusText(g){if(!g)return '';if(g.state==='lighting')return '灯语进行中'+(g.demo?' · 演示':'');if(g.state==='motion')return (g.motion==='nod'?'点头':'起伏')+'进行中'+(g.demo?' · 演示':'');if(g.state==='completed')return '问候已结束';if(g.state==='idle')return '站稳后选择动作';return g.message||'问候已停止';}
update=function(...args){greetingOriginalUpdate.apply(this,args);if(S?.greeting)text('greeting-status',greetingStatusText(S.greeting));};
